BEGIN TRANSACTION;
CREATE TABLE "account_status_history" ("history_id" TEXT PRIMARY KEY, "account_id" TEXT, "old_status" TEXT, "new_status" TEXT, "changed_at" TEXT, "reason" TEXT);
CREATE TABLE "accounts" ("account_id" TEXT PRIMARY KEY, "customer_id" TEXT, "account_type" TEXT, "currency" TEXT, "status" TEXT, "opened_at" TEXT, "closed_at" TEXT, "overdraft_limit" TEXT, "opening_balance" TEXT, "current_balance" TEXT);
CREATE TABLE "alerts" ("alert_id" TEXT PRIMARY KEY, "rule_id" TEXT, "transaction_id" TEXT, "account_id" TEXT, "created_at" TEXT, "risk_score" INTEGER, "score_breakdown" TEXT, "evidence" TEXT, "status" TEXT);
CREATE TABLE "analyst_actions" ("action_id" TEXT PRIMARY KEY, "case_id" TEXT, "alert_id" TEXT, "analyst_id" TEXT, "analyst_role" TEXT, "action_type" TEXT, "disposition" TEXT, "notes" TEXT, "action_timestamp" TEXT);
CREATE TABLE "case_alerts" ("case_alert_id" TEXT PRIMARY KEY, "case_id" TEXT, "alert_id" TEXT, "linked_at" TEXT);
CREATE TABLE "cases" ("case_id" TEXT PRIMARY KEY, "customer_id" TEXT, "opened_at" TEXT, "status" TEXT, "priority_score" INTEGER, "final_disposition" TEXT, "closed_at" TEXT);
CREATE TABLE "customers" ("customer_id" TEXT PRIMARY KEY, "full_name" TEXT, "date_of_birth" TEXT, "country" TEXT, "kyc_status" TEXT, "kyc_risk_tier" TEXT, "kyc_verified_at" TEXT, "onboarded_at" TEXT, "status" TEXT);
CREATE TABLE "device_account_links" ("link_id" TEXT PRIMARY KEY, "device_id" TEXT, "account_id" TEXT, "first_seen_at" TEXT, "last_seen_at" TEXT);
CREATE TABLE "devices" ("device_id" TEXT PRIMARY KEY, "device_type" TEXT, "os_family" TEXT, "first_seen_at" TEXT);
CREATE TABLE "ground_truth" ("truth_id" TEXT PRIMARY KEY, "entity_type" TEXT, "entity_id" TEXT, "label_kind" TEXT, "issue_type" TEXT, "expected_decision" TEXT, "generating_rule" TEXT, "pattern_instance_id" TEXT);
CREATE TABLE "merchants" ("merchant_id" TEXT PRIMARY KEY, "merchant_name" TEXT, "category" TEXT, "country" TEXT, "risk_level" TEXT);
CREATE TABLE "risk_rules" ("rule_id" TEXT PRIMARY KEY, "rule_name" TEXT, "rule_type" TEXT, "description" TEXT, "parameters" TEXT, "weight" INTEGER, "effective_from" TEXT, "effective_to" INTEGER, "is_active" TEXT);
CREATE TABLE "transactions" ("transaction_id" TEXT PRIMARY KEY, "account_id" TEXT, "merchant_id" TEXT, "device_id" TEXT, "txn_timestamp" TEXT, "direction" TEXT, "amount" TEXT, "txn_type" TEXT, "channel" TEXT, "status" TEXT, "balance_after" TEXT);
CREATE TABLE "transfer_links" ("transfer_id" TEXT PRIMARY KEY, "debit_txn_id" TEXT, "credit_txn_id" TEXT, "source_account_id" TEXT, "destination_account_id" TEXT, "transfer_amount" TEXT, "initiated_at" TEXT, "status" TEXT);
COMMIT;
